<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import { h3FramesForSeconds } from '../../../shared/h3-parameters'
import { PhArrowRight, PhArrowUpRight, PhCheck, PhClock, PhFilmStrip, PhImage, PhMagicWand, PhSlidersHorizontal, PhUploadSimple, PhPlay, PhPuzzlePiece, PhInfo, PhVideoCamera } from '@phosphor-icons/vue'

defineProps<{ page: string }>()
const emit = defineEmits<{ action: [name: string, payload?: string] }>()
const mode = ref('image')
const resolution = ref('864 × 480')
const duration = ref('5.17 秒')
const customWidth = ref(864)
const customHeight = ref(480)
const customSeconds = ref(5)
const actualSeconds = computed(() => { try { return (h3FramesForSeconds(Number(customSeconds.value)) / 24).toFixed(2) } catch { return '待确认' } })
const model = ref('MiniMax H3')
const prompt = ref('清晨薄雾中的森林，阳光缓缓穿过树冠。镜头向前轻推，光线柔和，画面自然。')
const seed = ref('随机')
const transformMode = ref('style')
watch(mode, value => { if (value === 'image' && model.value === 'Wan2.1 T2V · 1.3B') model.value = 'MiniMax H3' })
const transformation = computed(() => ({ style: { label: '转换风格', description: '保留镜头内容，探索不同的画面质感。', step: '选择风格与提示词', image: '/forest-preview.webp' }, person: { label: '局部换人物', description: '通过人物素材与遮罩，调整指定区域。', step: '提供人物参考与遮罩', image: '/camera-studio.webp' }, background: { label: '更换背景', description: '保留主体，重新构建视频的场景氛围。', step: '提供背景参考与遮罩', image: '/coast-inspiration.webp' } }[transformMode.value as 'style' | 'person' | 'background']))
function previewDraft() {
  emit('action', 'draft', JSON.stringify({ mode: mode.value === 'image' ? '图生视频' : '文生视频', model: model.value, resolution: resolution.value === '自定义' ? `${customWidth.value} × ${customHeight.value}` : resolution.value, duration: duration.value === '自定义' ? `${actualSeconds.value} 秒` : duration.value, prompt: prompt.value, seed: seed.value }, null, 2))
}
</script>

<template>
  <section v-if="page === 'create'" class="creative-page">
    <header class="page-heading">
      <div><p class="eyebrow">图片与文字 · 本地创作</p><h1>生成工作台</h1><p class="intro">从一张图片，或一句想法开始。</p></div>
      <button class="button secondary" @click="emit('action', 'editor')"><PhSlidersHorizontal :size="18" />打开节点编辑器<PhArrowUpRight :size="15" /></button>
    </header>

    <div class="creation-tabs" role="group" aria-label="创作方式"><button class="current" @click="emit('action', 'create')">生成视频</button><button @click="emit('action', 'transform')">改造视频</button></div>
    <div class="studio-grid">
      <form class="parameter-card card" @submit.prevent="previewDraft">
        <div class="segmented" aria-label="生成方式"><button type="button" :class="{ chosen: mode === 'image' }" :aria-pressed="mode === 'image'" @click="mode = 'image'"><PhImage :size="18" />图生视频</button><button type="button" :class="{ chosen: mode === 'text' }" :aria-pressed="mode === 'text'" @click="mode = 'text'"><PhMagicWand :size="18" />文生视频</button></div>
        <div v-if="mode === 'image'" class="first-frame">
          <div class="label-row"><span class="field-label">首帧图片</span><span class="field-help">PNG / JPG / WebP</span></div>
          <button class="frame-upload" type="button" @click="emit('action', 'image')"><img src="/forest-preview.webp" alt="晨光森林首帧静态样例" /><span class="sample-chip">静态样例</span><span class="upload-label"><PhUploadSimple :size="16" />选择首帧图片</span></button>
        </div>
        <div v-else class="text-hint"><PhMagicWand :size="23" /><div><strong>无需首帧图片</strong><p>描述场景、主体和镜头运动，让文字成为起点。</p></div></div>
        <label class="field prompt-field"><span class="field-label">画面描述</span><textarea v-model="prompt" rows="4" maxlength="10000" placeholder="描述你想看到的场景与镜头运动…"></textarea><span class="field-help">具体描述主体、光线和镜头，有助于稳定画面。</span></label>
        <label class="field"><span class="field-label">视频模型</span><select v-model="model" aria-label="视频模型"><option>MiniMax H3</option><option disabled>其他模型 · 在原生编辑器配置</option></select></label>
        <div class="two-fields"><label class="field"><span class="field-label">分辨率</span><select v-model="resolution"><option>864 × 480</option><option>1280 × 704</option><option>480 × 864</option><option>768 × 768</option><option>自定义</option></select></label><label class="field"><span class="field-label">时长</span><select v-model="duration"><option>5.17 秒</option><option>2.33 秒</option><option>10.13 秒</option><option>15.08 秒</option><option>自定义</option></select></label></div>
        <div v-if="resolution === '自定义'" class="two-fields"><label class="field">宽度<input v-model="customWidth" type="number" min="256" max="1344" step="32" /></label><label class="field">高度<input v-model="customHeight" type="number" min="256" max="1344" step="32" /></label></div>
        <label v-if="duration === '自定义'" class="field">期望秒数<input v-model="customSeconds" type="number" min="1" max="15" step="0.1" /><span class="field-help">按模型帧数规则换算，实际约 {{ actualSeconds }} 秒。</span></label>
        <details class="advanced"><summary>高级参数<PhSlidersHorizontal :size="16" /></summary><label class="field"><span class="field-label">种子</span><input v-model="seed" aria-label="种子" /><span class="field-help">示例选项。正式运行时需匹配所选工作流。</span></label></details>
        <button class="button primary generate" type="submit"><PhPlay :size="18" weight="fill" />生成视频<PhArrowRight :size="18" /></button>
        <p class="form-footnote">设计预览 · 当前操作不会提交生成任务</p>
      </form>

      <div class="preview-column">
        <section class="preview-card card" aria-labelledby="preview-title">
          <div class="section-top"><h2 id="preview-title">画面预览</h2><span class="neutral-badge"><span></span>静态样例</span></div>
          <div class="preview-image"><img src="/forest-preview.webp" alt="清晨森林视频画面静态样例" /><div class="preview-caption"><span>Morning in the woods</span><span>864 × 480</span></div></div>
          <div class="preview-toolbar"><div class="preview-file"><span class="small-icon"><PhFilmStrip :size="20" /></span><div><strong>晨光森林</strong><p>MiniMax H3 · 5.17 秒 · 示例画面</p></div></div><button class="icon-button" aria-label="查看导出说明" @click="emit('action', 'export')"><PhArrowUpRight :size="20" /></button></div>
        </section>
        <section class="readiness card"><div class="ready-icon"><PhCheck :size="19" weight="bold" /></div><div><h3>创作前，先确认运行环境</h3><p>模型与 ComfyUI 状态，以设备实际检测结果为准。</p></div><button class="text-button" @click="emit('action', 'environment')">检查环境<PhArrowRight :size="16" /></button></section>
        <section class="recent-task card"><div class="section-top"><h2>最近任务</h2><button class="text-button" @click="emit('action', 'task')">查看全部<PhArrowRight :size="16" /></button></div><button class="task-row" @click="emit('action', 'task')"><img src="/coast-inspiration.webp" alt="海岸镜头任务静态缩略图" /><div><strong>海岸的慢镜头</strong><p>图生视频 · MiniMax H3</p></div><span class="task-status"><PhClock :size="15" />历史样例</span><PhArrowUpRight :size="17" /></button></section>
      </div>
    </div>
  </section>

  <section v-else class="creative-page transform-page">
    <header class="page-heading"><div><p class="eyebrow">视频改造 · 灵感重绘</p><h1>视频改造</h1><p class="intro">延续一个镜头，探索新的表达。</p></div><button class="button secondary" @click="emit('action', 'editor')"><PhPuzzlePiece :size="18" />在节点编辑器中创作<PhArrowUpRight :size="15" /></button></header>
    <div class="creation-tabs" role="group" aria-label="创作方式"><button @click="emit('action', 'create')">生成视频</button><button class="current" @click="emit('action', 'transform')">改造视频</button></div>
    <div class="transform-options" aria-label="视频改造方式">
      <button class="transform-option" :class="{ selected: transformMode === 'style' }" :aria-pressed="transformMode === 'style'" @click="transformMode = 'style'"><span class="option-icon"><PhMagicWand :size="25" /></span><span><strong>转换风格</strong><span>改变画面质感，保留镜头内容</span></span><span class="option-radio"><PhCheck v-if="transformMode === 'style'" :size="13" weight="bold" /></span></button>
      <button class="transform-option" :class="{ selected: transformMode === 'person' }" :aria-pressed="transformMode === 'person'" @click="transformMode = 'person'"><span class="option-icon"><PhImage :size="25" /></span><span><strong>局部换人物</strong><span>替换指定区域中的人物</span></span><span class="option-radio"><PhCheck v-if="transformMode === 'person'" :size="13" weight="bold" /></span></button>
      <button class="transform-option" :class="{ selected: transformMode === 'background' }" :aria-pressed="transformMode === 'background'" @click="transformMode = 'background'"><span class="option-icon"><PhVideoCamera :size="25" /></span><span><strong>更换背景</strong><span>保留主体，重新构建场景</span></span><span class="option-radio"><PhCheck v-if="transformMode === 'background'" :size="13" weight="bold" /></span></button>
    </div>
    <div class="transform-grid">
      <section class="transform-main card"><div class="section-top"><div><h2>{{ transformation.label }}</h2><p>{{ transformation.description }}</p></div><span class="neutral-badge">工作流方式</span></div><div class="transform-example"><img :src="transformation.image" :alt="transformation.label + '静态场景示意'" /><span class="sample-chip">场景示意 · 非改造结果</span></div><div class="steps"><div><span>01</span><strong>导入原始视频</strong><p>选取短片，确认帧率与尺寸。</p></div><div><span>02</span><strong>{{ transformation.step }}</strong><p>在编辑器中检查输入节点。</p></div><div><span>03</span><strong>检查依赖并运行</strong><p>先用短片验证，再完整制作。</p></div></div></section>
      <aside class="transform-sidebar">
        <section class="card workflow-card"><span class="workflow-symbol"><PhPuzzlePiece :size="29" /></span><h2>把想法放进工作流</h2><p>视频改造需要匹配的模型、节点与工作流。在原生 ComfyUI 编辑器中配置素材和参数。</p><button class="button primary" @click="emit('action', 'add-workflow')">添加改造工作流<PhArrowRight :size="18" /></button><button class="button secondary" @click="emit('action', 'import')">导入已有 JSON<PhUploadSimple :size="18" /></button><p class="card-footnote">设计预览 · 按钮展示操作说明</p></section>
        <section class="card preparation"><h3>开始前准备</h3><ul><li><PhCheck :size="17" /><span>可读取的原始视频</span></li><li><PhCheck :size="17" /><span>{{ transformMode === 'style' ? '风格提示词或参考图片' : '参考图片与区域遮罩' }}</span></li><li><PhCheck :size="17" /><span>对应模型与自定义节点</span></li></ul><button class="text-button" @click="emit('action', 'environment')">查看运行环境<PhArrowRight :size="16" /></button></section>
      </aside>
    </div>
    <div class="transform-note"><PhInfo :size="19" /><p>不同工作流对视频长度、分辨率与显存的要求不同。建议先用 3–5 秒素材测试，并保留原始文件。</p></div>
  </section>
</template>

